import test from 'node:test';
import assert from 'node:assert/strict';
import { formatLabel, decoratedLabel } from '../src/format-label.js';
test('format valid label and preserve case', t => { assert.equal(formatLabel('MiXeD'), 'MiXeD'); t.diagnostic('BODY:format-valid'); });
test('reject blank label', t => { assert.throws(() => formatLabel('   '), /blank/); t.diagnostic('BODY:format-blank'); });
test('decorate with configured suffix', t => { assert.equal(decoratedLabel('hello'), 'hello!'); t.diagnostic('BODY:format-config'); });
test('trim surrounding whitespace while preserving case and interior spaces', () => {
  assert.equal(formatLabel('  MiXeD  '), 'MiXeD');
  assert.equal(formatLabel('\t\nAlpha\r\n'), 'Alpha');
  assert.equal(formatLabel(' a B '), 'a B');
});
test('reject every blank string form', () => {
  for (const value of ['', '   ', '\t\n\r']) {
    assert.throws(() => formatLabel(value), /blank/);
  }
});
test('decorate trimmed labels and reject blank input', () => {
  assert.equal(decoratedLabel('  MiXeD  '), 'MiXeD!');
  assert.throws(() => decoratedLabel('\t\n'), /blank/);
});

